    // TODO(translate): port src/ulidgen.c::main
    //  1. parse std::env::args().skip(1):
    //     -n N -> n: i64 (parse error -> usage to stderr, exit(1))
    //     -t   -> tag mode
    //     unknown flag -> usage to stderr, exit(1)
    //  2. tag mode: for each line from stdin (BufRead::read_line, keeps '\n'),
    //     ulidgen_r(&mut ulid); write "<ulid> <line>"; flush after EACH line
    //     (mirrors setvbuf(stdout, _IOLBF))
    //  3. generate mode: loop 0..n, ulidgen_r(&mut ulid), print the 26 chars
    //  4. on any stdout write error: process::exit(1)
    let _ = (io::stdin, process::exit);
